import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data or len(data) < 2:
        print(-1)
        return

    try:
        N = int(data[0])
        X = int(data[1])

        if N < 0 or X < 0:
            print(-1)
            return

        if N == 0:
            print(0)
            return

        waiting_time = (N - 1) * X + N * 10
        print(waiting_time)
    except (ValueError, IndexError):
        print(-1)
        return

if __name__ == "__main__":
    main()
